import{_ as a,o as e,c as l,a as r}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"10. 安全生产与职业健康","description":"","frontmatter":{},"headers":[],"relativePath":"theory/10-safety-health.md","filePath":"theory/10-safety-health.md","lastUpdated":1787294102000}'),i={name:"theory/10-safety-health.md"};function o(d,t,n,h,s,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="_10-安全生产与职业健康" tabindex="-1">10. 安全生产与职业健康 <a class="header-anchor" href="#_10-安全生产与职业健康" aria-label="Permalink to &quot;10. 安全生产与职业健康&quot;">​</a></h1><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><p>学完本章，你应该能识别消防设施岗位的主要危险，完成作业前安全确认，知道何时停止操作并报告，以及如何留下可追溯记录。</p><h2 id="一、风险、危险源和隐患" tabindex="-1">一、风险、危险源和隐患 <a class="header-anchor" href="#一、风险、危险源和隐患" aria-label="Permalink to &quot;一、风险、危险源和隐患&quot;">​</a></h2><ul><li><strong>危险源</strong>是可能造成伤害或损失的根源，例如带电端子、高速旋转风机、下降中的卷帘和浓烟环境。</li><li><strong>风险</strong>是危险发生的可能性与后果严重程度的组合。</li><li><strong>事故隐患</strong>是可能导致事故的人的不安全行为、物的不安全状态、环境问题或管理缺陷。</li></ul><p>零基础判断风险时，可以问三个问题：会伤到谁？什么时候会发生？怎样消除或降低风险？</p><h2 id="二、作业前-先确认再动手" tabindex="-1">二、作业前：先确认再动手 <a class="header-anchor" href="#二、作业前-先确认再动手" aria-label="Permalink to &quot;二、作业前：先确认再动手&quot;">​</a></h2><ol><li>明确任务、设备、区域和授权范围；</li><li>查阅设备说明书、单位规程和应急预案；</li><li>了解是否影响报警、灭火、排烟、疏散和通信；</li><li>确认停送电、隔离、监护、告知和恢复措施；</li><li>检查工具、仪表和防护用品是否完好；</li><li>设定停止条件：出现烟气、异味、异常声音、误动作、人员进入危险区时立即停止并报告。</li></ol><h2 id="三、作业中-不同危险不同防护" tabindex="-1">三、作业中：不同危险不同防护 <a class="header-anchor" href="#三、作业中-不同危险不同防护" aria-label="Permalink to &quot;三、作业中：不同危险不同防护&quot;">​</a></h2><ul><li><strong>电气风险</strong>：断电、验电、防止误送电；不得湿手操作，不带电拆装。</li><li><strong>机械风险</strong>：泵、风机、卷帘运行时远离转动和运动部件；清洁维护前确认停机。</li><li><strong>高处风险</strong>：使用合格梯具和防坠措施，不站在不稳定物体上。</li><li><strong>烟气和有毒环境</strong>：不盲目进入浓烟、缺氧或疑似爆炸区域，按预案撤离和报警。</li><li><strong>动火风险</strong>：执行审批、清理可燃物、配备灭火器材、专人监护并复查余火。</li></ul><h2 id="四、作业后-恢复和记录同样重要" tabindex="-1">四、作业后：恢复和记录同样重要 <a class="header-anchor" href="#四、作业后-恢复和记录同样重要" aria-label="Permalink to &quot;四、作业后：恢复和记录同样重要&quot;">​</a></h2><p>作业结束不是“按钮按完了”，而是要确认：防护罩和部件恢复、阀门处于规定状态、报警/联动/自动状态恢复、现场无工具和火种、控制器无新增异常、相关人员已获知结果。</p><p>记录至少包括时间、地点、设备、现象、操作、测试结果、异常、临时措施、报告对象和后续责任人。</p><h2 id="五、个人防护用品与特殊作业边界" tabindex="-1">五、个人防护用品与特殊作业边界 <a class="header-anchor" href="#五、个人防护用品与特殊作业边界" aria-label="Permalink to &quot;五、个人防护用品与特殊作业边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>重点防护/控制</th><th>不能替代的措施</th></tr></thead><tbody><tr><td>带电检查或电气故障</td><td>按作业等级选择绝缘防护、验电和监护</td><td>个人防护用品不能替代断电隔离</td></tr><tr><td>高处检查灯具、风阀或探测器</td><td>合格梯具、稳定站位和防坠措施</td><td>不能站在箱体、椅子或临时垫物上</td></tr><tr><td>泵房、风机房和卷帘区域</td><td>防机械运动、噪声、滑倒和误启动</td><td>不能只靠口头提醒代替警戒和停机确认</td></tr><tr><td>烟气、有限空间或疑似缺氧环境</td><td>立即撤离、警戒、通风和专业救援</td><td>普通口罩或湿毛巾不能作为进入许可</td></tr><tr><td>动火作业</td><td>审批、清理可燃物、灭火器材、监护和复查</td><td>不能用“现场有人看着”代替动火制度</td></tr></tbody></table><h2 id="六、锁定挂牌与能量控制" tabindex="-1">六、锁定挂牌与能量控制 <a class="header-anchor" href="#六、锁定挂牌与能量控制" aria-label="Permalink to &quot;六、锁定挂牌与能量控制&quot;">​</a></h2><p>“断电”只是开始。<strong>锁定挂牌与能量控制</strong>可以先理解成：不仅把设备停下来，还要防止它在作业过程中突然重新获得能量或突然运动。</p><p>以消防泵或风机为例：</p><ol><li>明确哪台设备、哪种能量有危险，不能只看电源，还要考虑水压、气压、旋转惯性和重力；</li><li>找到对应的隔离点，例如批准的电源开关、控制柜隔离位置或其他规定隔离部位；</li><li>按单位制度由有权限人员执行隔离、锁定或挂牌，并让作业人员知道设备正在作业；</li><li>用规定方法验证设备不会启动、不会继续转动或不会释放危险压力；“开关在断开”不等于验证完成；</li><li>作业中不得擅自解除他人锁定或跳过监护；</li><li>恢复前清点人员和工具，确认防护装置、阀门、控制方式和现场区域恢复，通知相关人员，再按程序解除隔离。</li></ol><p>零基础学习者只需要先记住：<strong>停机、隔离、锁定/标识、验证、作业、清点、通知、恢复</strong>。如果不知道隔离点在哪里，或没有相应授权，就不能自行尝试。</p><h2 id="七、应急处置场景" tabindex="-1">七、应急处置场景 <a class="header-anchor" href="#七、应急处置场景" aria-label="Permalink to &quot;七、应急处置场景&quot;">​</a></h2><p>如果启动消防泵后出现异常振动或压力异常：不要为了完成步骤继续运行，也不要立即拆泵。先按规程停止或采取安全措施，保护人员，报告负责人，记录现象，并由专业人员判断机械、电气、阀门和管网原因。</p><h2 id="八、自测" tabindex="-1">八、自测 <a class="header-anchor" href="#八、自测" aria-label="Permalink to &quot;八、自测&quot;">​</a></h2><ol><li>作业前为什么要先确认联动影响？</li><li>“断电”与“验电”为什么不能只做一个？</li><li>哪些情况必须立即停止操作？</li><li>记录中为什么要写临时措施和报告对象？</li></ol><blockquote><p>参考：<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">《中华人民共和国安全生产法》</a>、<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">《中华人民共和国消防法》</a>及<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a>。</p></blockquote>',25)])])}const p=a(i,[["render",o]]);export{b as __pageData,p as default};
